const BALANCE_NORMAL_2 = {"early":[["corpse"],["soldier"],["corpse","warrior"]],"late":[["corpse@1","corpse","corpse@3"],["soldier","bone"],["bone","warrior","warrior@1"],["warrior","warrior","spirit"]]};
// ACT2 uses explicit action records. Ability bonuses are read dynamically.
const SNOW_FOES={corpse:['呪いの屍','♟',30,[{curse:4},{d:10},{d:4,h:2},{b:5}]],soldier:['凍える屍兵','⚔',40,[{d:2,h:3},{d:10},{freeze:2}]],bone:['灰の骨兵','☠',50,[{b:10},{d:2,h:4},{curse:3},{d:12},{d:3,h:2}]],warrior:['死の戦士','†',40,[{d:4},{curse:2}]],spirit:['怨念','☽',26,[{curse:8},{freeze:1},{b:10},{d:1,h:5},{s:1}]],hand:['悪魔の手','✋',70,[{d:12},{curse:4},{d:5,h:2},{s:2}]],finger:['悪魔の指','☝',34,[{d:7},{curse:3,s:1},{d:8},{curseUp:1}]],breaker:['鎧砕き','⚒',100,[{armor:2},{d:10},{d:4,h:2},{d:20},{s:1}]],storm:['雪嵐','❄',60,[{d:2,h:3},{d:3,h:3},{d:1,h:5},{freeze:2}]],giant:['雪の巨人','♜',100,[{d:10,freeze:3},{d:5,h:3},{allyBlock:10,freezeUp:1},{s:1}]],ice:['氷竜','♞',190,[{freeze:3},{d:10},{b:10},{empower:'corpseDragon'}]],corpseDragon:['屍竜','♞',220,[{d:4,h:2},{curse:3},{d:4,h:4},{empower:'ice'}]]};

const SNOW_ICON_PATHS={hand:'M18 54L16 39 8 29Q5 24 9 22L20 31 14 12Q13 7 17 7Q21 7 23 20L27 29 24 7Q24 3 28 3Q32 3 32 17L34 29 36 8Q37 4 41 6Q44 8 41 23L40 33 46 17Q48 13 51 16Q54 18 48 36L47 44 41 55ZM21 43L28 39 34 44 40 38M25 51L33 48',finger:'M23 56L19 42 23 29 26 8Q27 3 31 4Q36 5 34 15L34 30 42 35 46 44 40 56ZM26 20L34 21M23 34L34 37M26 45L39 45',dragon:'M12 52L18 39 10 34 21 31 17 20 27 24 31 8 37 18 50 12 47 26 58 32 51 42 41 44 34 55ZM31 25L39 27 47 31 40 36 48 37M30 34L23 40 27 49M19 39L14 49M36 18L40 21M40 28L43 29'};
function snowDragonIcon(key){const ice=key==='ice';return '<svg class="enemy-art dragon-art '+(ice?'ice-dragon':'corpse-dragon')+'" viewBox="0 0 96 96" aria-hidden="true"><g fill="currentColor" fill-opacity=".38" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M44 61L26 53 9 28 30 34 26 13 49 35 56 54M48 59L65 42 74 22 81 40 92 36 84 63 65 68"/><path d="M20 80Q5 79 9 65Q13 78 27 69L42 57Q40 42 51 32L60 27 57 15 67 23 74 13 74 27 88 33 89 41 77 45 68 40Q60 49 66 62L74 77 84 81 76 85 65 80 56 69 45 71 43 82 32 85 28 81 36 77 36 71Q27 82 20 80Z"/><path d="M29 35L46 52M16 33L33 49M75 43L65 60M83 47L75 62M77 36L81 36M80 43L79 48M74 43L73 47" fill="none"/>'+(ice?'<path d="M50 33L44 25 55 28M44 46L37 40 44 40M60 60L70 55M55 65L61 73" fill="none"/>':'<path d="M67 31L74 30 73 37 67 37ZM63 50L61 61M49 62L57 67M54 56L63 59M69 76L75 77" fill="none"/>')+'</g></svg>';}
function snowEnemyIcon(key){if(key==='ice'||key==='corpseDragon')return snowDragonIcon(key);const path=SNOW_ICON_PATHS[key==='ice'||key==='corpseDragon'?'dragon':key];return path?'<svg class="enemy-art" viewBox="0 0 64 64" aria-hidden="true"><path d="'+path+'" fill="currentColor" fill-opacity=".16" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>':SNOW_FOES[key][1];}
for(const key of ['hand','finger','ice','corpseDragon'])SNOW_FOES[key][1]=snowEnemyIcon(key);
for(const e of S.run?.enemies||[])if(e.act2&&SNOW_FOES[e.snowKey])e.icon=SNOW_FOES[e.snowKey][1];

function snowFoe(key,offset=0,hp){const [name,icon,max]=SNOW_FOES[key];return Object.assign(enemy(name,icon,hp||max,0),{act2:true,snowKey:key,actionStep:offset,str:0,dragonHead:key==='ice'||key==='corpseDragon'});}
function snowEncounter(r,type){if(type==='boss')return [snowFoe('ice'),snowFoe('corpseDragon')];if(type==='elite'){r.snowElitePool??=[];if(!r.snowElitePool.length)r.snowElitePool=shuffle(['hand','breaker','storm']);const k=r.snowElitePool.pop();return k==='storm'?[snowFoe('storm'),snowFoe('giant')]:[snowFoe(k)];}r.snowFights=(r.snowFights||0)+1;const candidates=BALANCE_NORMAL_2[r.snowFights<=3?'early':'late'];return (typeof balanceEncounterPick==='function'?balanceEncounterPick(2,candidates):rand(candidates)).map(entry=>{const [key,offset]=entry.split('@');return snowFoe(key,Number(offset)||0);});}
keywords.凍結='ブロックを得るカードのコストが+1される。ブロックを得るたび1減少し、ターン終了時に1減少する。';
keywords.呪い='呪い1につき最大HPが2減少する（最低1）。攻撃するたび呪いが1減少する。呪いが減少すると、その分だけ減少していた最大HPを取り戻し、最大HPの低下に合わせて切り下げられた現在HPだけを取り戻す。もともと受けていたダメージは回復しない。戦闘終了時に解除される。';
keywords.甲撃='対象にブロックが10以上あるなら攻撃ダメージを2倍にする。攻撃ダメージを与えるたび1減少する。';
// Record the actual loss per stack, including partial stacks at the maximum-HP floor.
function migrateCurse(e){if(!e)return;if(!Array.isArray(e.curseLosses))e.curseLosses=Array(Math.max(0,e.curse||0)).fill(1);e.curseMaxLoss=e.curseLosses.reduce((n,v)=>n+v,0);if(!Array.isArray(e.curseHpLosses))e.curseHpLosses=e.curseLosses.map(()=>0);}
function applyCurse(e,n){migrateCurse(e);n=Math.max(0,Math.floor(n));for(let i=0;i<n;i++){const loss=Math.min(2,Math.max(0,e.max-1));e.curseLosses.push(loss);e.curseMaxLoss+=loss;e.max-=loss;const clipped=Math.max(0,e.hp-e.max);e.curseHpLosses.push(clipped);e.hp-=clipped;}e.curse=(e.curse||0)+n;}
function releaseCurse(e,n=1){migrateCurse(e);n=Math.min(Math.max(0,n),e.curse||0);const restored=e.curseLosses.splice(0,n).reduce((sum,v)=>sum+v,0),hp=e.curseHpLosses.splice(0,n).reduce((sum,v)=>sum+v,0);e.curse=(e.curse||0)-n;e.curseMaxLoss=Math.max(0,(e.curseMaxLoss||0)-restored);e.max+=restored;if(e.hp>0)healHP(e,hp);}
function snowMate(r,e){return r.enemies.find(x=>x!==e&&x.dragonHead&&x.hp>0);}
function snowStrength(r,e){return (e.str||0)+(e.snowKey==='giant'?Math.floor((r.freeze||0)/3):e.snowKey==='corpseDragon'&&snowMate(r,e)?Math.floor((r.freeze||0)/2):0);}
function updateSoloDragon(r,e){if(!e.dragonHead||e.hp<=0||e.soloDragon)return;if(r.enemies.some(x=>x!==e&&x.dragonHead&&x.hp<=0)){e.soloDragon=true;e.dragonBonus=0;}}
const SOLO_DRAGON_ACTIONS={ice:[{d:10,freeze:5},{d:5,h:2},{d:5,h:3,freeze:3},{s:2,freezeUp:1}],corpseDragon:[{d:13},{b:16,curse:4},{d:3,h:8},{s:2,curseUp:2}]};
function planSnow(r){for(const e of r.enemies||[]){if(!e.act2||e.hp<=0)continue;const list=SNOW_FOES[e.snowKey][3];updateSoloDragon(r,e);let a={...list[e.actionStep%list.length]};if(e.dragonHead&&!snowMate(r,e))a={...SOLO_DRAGON_ACTIONS[e.snowKey][e.actionStep%4]};if(a.allyBlock&&!r.enemies.some(x=>x.snowKey==='storm'&&x.hp>0))delete a.allyBlock;if(a.curse)a.curse+=(e.curseBonus||0)+(e.dragonBonus||0);if(a.freeze)a.freeze+=(e.dragonBonus||0)+(e.freezeBonus||0);e.snowAction=a;e.intent=a.d!=null?'attack':a.b?'guard':'snowAction';e.atk=a.d||0;e.hits=a.h||1;e.guardAmount=(a.b||0)+(e.snowKey==='ice'&&snowMate(r,e)?(r.curse||0):0);e.move=a.d?'攻撃':a.b?'防御':a.curse?'呪い':a.freeze?'凍結':'強化';if(e.hunterStun){e.intent='stunned';e.move='スタン';}if(e.snowStartTurn!==r.turn){e.snowStartTurn=r.turn;if(e.snowKey==='ice')e.block+=(r.freeze||0)*2;}}}
function snowAction(r,e){const a=e.snowAction||{};if(a.curse)applyCurse(r,a.curse);if(a.freeze)r.freeze=(r.freeze||0)+a.freeze;if(a.s)e.str=(e.str||0)+a.s;if(a.armor)e.armorStrike=(e.armorStrike||0)+a.armor;if(a.curseUp)e.curseBonus=(e.curseBonus||0)+a.curseUp;if(a.freezeUp)e.freezeBonus=(e.freezeBonus||0)+a.freezeUp;if(a.selfInflictUp)e.selfInflictBonus=(e.selfInflictBonus||0)+a.selfInflictUp;if(a.allyBlock){const ally=r.enemies.find(x=>x.snowKey==='storm'&&x.hp>0);if(ally)ally.block+=a.allyBlock;}if(a.empower){const mate=snowMate(r,e);if(mate)mate.dragonBonus=(mate.dragonBonus||0)+2;}}
const snowChooseBase=choose;choose=function(type){const r=S.run,was=r?.mode;snowChooseBase(type);if(r===S.run&&r?.act===2&&was!=='battle'&&page==='battle'&&['fight','elite','boss'].includes(type)){releaseCurse(r,r.curse);r.freeze=0;r.armorStrike=0;r.enemies=snowEncounter(r,type);target=0;healthVisuals.clear();planSnow(r);render();}};
const snowPlanBase=prepareEncounterTurn;prepareEncounterTurn=function(r){snowPlanBase(r);if(r.act===2)planSnow(r);};
const snowBossBase=bossPlan;bossPlan=function(r){if(r.act===2){planSnow(r);return;}snowBossBase(r);};
const snowEnemyAttackBase=enemyAttack;enemyAttack=function(e){return e.act2?Math.max(0,e.atk+snowStrength(S.run,e)):snowEnemyAttackBase(e);};
const snowActionEndBase=hunterEnemyActionEnd;hunterEnemyActionEnd=function(r,e){snowActionEndBase(r,e);if(e.act2){e.actionStep++;}};
const snowTurnEndBase=hunterPlayerTurnEnd;hunterPlayerTurnEnd=function(r){snowTurnEndBase(r);r.freeze=Math.max(0,(r.freeze||0)-1);};
const snowBlockBase=gainBlock;gainBlock=function(r,n,source){const gained=snowBlockBase(r,n,source);if(gained>0)r.freeze=Math.max(0,(r.freeze||0)-1);return gained;};
const snowCardBase=combatCard;combatCard=function(id){const c=snowCardBase(id),r=S.run;if(!c||!r?.freeze)return c;const f=c.fx,blocks=f.b||f.strengthBlock||f.exhaustBlock||f.poisonBlock;return blocks?{...c,cost:c.cost+1,frozenCost:true}:c;};
const snowDamageBase=dealDamage;dealDamage=function(e,n,options={}){const r=S.run,a=options.attacker,alive=e?.hp>0;if(options.attack&&a?.armorStrike&&e.block>=10)n*=2;const lost=snowDamageBase(e,n,options);if(options.attack&&a){releaseCurse(a);if(lost>0&&a.armorStrike)a.armorStrike--;if(a.snowKey==='storm'&&lost>0)e.freeze=(e.freeze||0)+1;if(a.snowKey==='corpseDragon'&&e===r&&lost>0)applyCurse(r,1);}if(alive&&e.hp<=0&&e.act2&&!e.snowDeathHandled){e.snowDeathHandled=true;if(e.snowKey==='hand'){const fingers=[snowFoe('finger'),snowFoe('finger'),snowFoe('finger',1,36),snowFoe('finger',1,36)];if(r.enemyPhase)for(const f of fingers)f.summonedTurn=r.turn;r.enemies.push(...fingers);planSnow(r);}if(e.dragonHead){const mate=snowMate(r,e);if(mate){mate.dragonBonus=0;planSnow(r);}}}return lost;};
function intentStatus(name,value){return '<span class="status-help intent-status" tabindex="0"><strong>'+name+' '+value+'</strong><aside class="tooltip">'+(keywords[name]||name)+'</aside></span>';}
const snowIntentBase=intent;intent=function(e){if(!e.act2)return snowIntentBase(e);if(e.hunterStun||e.intent==='stunned')return '<strong>⏸ スタン</strong><small>行動不能</small>';if(e.intent==='attack'){const a=e.snowAction||{};return '<strong>⚔ '+enemyAttack(e)+(e.hits>1?' × '+e.hits:'')+'</strong>'+(a.freeze?intentStatus('凍結',a.freeze):'')+'<small>攻撃</small>';}if(e.intent==='guard'){const a=e.snowAction||{};return '<strong>◇ '+e.guardAmount+'</strong>'+(a.curse?intentStatus('呪い',a.curse):'')+'<small>防御</small>';}const a=e.snowAction||{};return [a.curse?intentStatus('呪い',a.curse):'',a.freeze?intentStatus('凍結',a.freeze):'',a.s?intentStatus('筋力','+'+a.s):'',a.armor?intentStatus('甲撃',a.armor):'',a.allyBlock?intentStatus('ブロック',a.allyBlock):'',a.freezeUp?'<strong>凍結付与量 +'+a.freezeUp+'</strong>':'',a.curseUp?'<strong>呪い付与量 +'+a.curseUp+'</strong>':'',a.empower?'<strong>'+(e.snowKey==='ice'?'呪い':'凍結')+'付与量 +2</strong>':''].filter(Boolean).join('')+'<small>強化・状態付与</small>';};
function enemyAbilities(e){const r=S.run;switch(e.snowKey){case 'hand':return [['分裂','死亡時、悪魔の指を4体召喚する。']];case 'storm':return [['吹雪','攻撃ダメージによってHPを減少させるたび、凍結1を与える。']];case 'giant':return [['凍気','プレイヤーの凍結3につき筋力1を得る。現在：筋力+'+Math.floor((r?.freeze||0)/3)+'。']];case 'ice':return [['凍鱗','ターン開始時、プレイヤーの凍結1につき2ブロックを得る。'],['屍竜の庇護','屍竜の生存時、プレイヤーの呪い1につき守護1を得る。現在：守護+'+(r&&snowMate(r,e)?r.curse||0:0)+'。']];case 'corpseDragon':return [['屍噛','屍竜の攻撃によってHPを減少させるたび、呪い1を付与する。この付与量は増加しない。'],['氷竜の恩寵','氷竜の生存時、プレイヤーの凍結2につき筋力1を得る。現在：筋力+'+(r&&snowMate(r,e)?Math.floor((r.freeze||0)/2):0)+'。']];}if(e.behavior==='ravager')return [['激昂','毎ターン攻撃+2。5ターン目から2回攻撃する。']];if(e.behavior==='plated')return [['堅牢な甲羅','初期ブロック50。ターン開始時にブロックを失わない。']];return [];}
function enemyAbilitiesHTML(e){const abilities=enemyAbilities(e).filter(([name])=>name!=='氷竜の恩寵'&&name!=='屍竜の庇護'||!!snowMate(S.run,e));return abilities.length?'<div class="enemy-abilities '+(e.dragonHead||e.boss?'boss-abilities':'')+'">'+abilities.map(([name,desc])=>'<span class="status-help enemy-ability" tabindex="0">'+name+'<aside class="tooltip">'+desc+'</aside></span>').join('')+'</div>':'';}
function snowStatus(e){return [['freeze','凍結'],['curse','呪い'],['armorStrike','甲撃']].map(([k,n])=>e[k]?statusEffectHTML(n,e[k]):'').join('');}
const snowStatusBase=enemyStatusHTML;enemyStatusHTML=function(e){return enemyAbilitiesHTML(e)+snowStatusBase(e);};
const snowBattleBase=battle;battle=function(){let html=snowBattleBase(),r=S.run;html=html.replace('<div class="player-status">','<div class="player-status">'+snowStatus(r));if(r.act===2){html=html.replace(/<h2>[^<]*<\/h2>/,'<h2>'+(r.kind==='boss'?'双頭の山竜':r.kind==='elite'?'屍雪山の強敵':'屍雪山')+'</h2>').replace(/<div class="arena[^\"]*">/,'<div class="arena'+(r.enemies.filter(e=>e.hp>0).length>=3?' crowded-encounter':'')+'">');}if(r.curseMaxLoss){const total=r.max+r.curseMaxLoss,ratio=r.curseMaxLoss/total*100;html=html.replace('<div class="health-track">','<div class="health-track" style="--curse-loss:'+ratio+'%"><i class="curse-loss" style="left:auto;right:0;width:'+ratio+'%"></i>');} return html;};
const snowFinishBase=finish;finish=function(...args){if(S.run)releaseCurse(S.run,S.run.curse);return snowFinishBase(...args);};
if(S.run?.act===2&&S.run.mode==='battle')planSnow(S.run);


const snowCardHTMLBase=card;card=function(id,...args){let html=snowCardHTMLBase(id,...args);if(page==='battle'&&S.run&&combatCard(id)?.frozenCost)html=html.replace('class="cost"','class="cost frozen-cost"');return html;};
for(const e of [S.run,...(S.run?.enemies||[])])if(e)migrateCurse(e);
// End curse before victory rewards and map/rest/event access.
const curseVictoryBase=victory;victory=function(){const r=S.run;if(r?.mode==='battle'&&r.enemies?.every(e=>e.hp<=0))releaseCurse(r,r.curse);return curseVictoryBase();};
if(S.run&&S.run.mode!=='battle')releaseCurse(S.run,S.run.curse);
if(!globalThis.ASHBOUND_HEADLESS)render();
